INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_CIV','The Republic of First Drafts');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_CIV5_HEADING_1','Nothing Is Ever Final');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_CIV5_TEXT_1','The Republic of First Drafts unites writers, architects, engineers, scholars and publishers around one conviction: Nothing Is Ever Final. Its government rewards new institutions and treats experimentation as a civic duty. The Editorial Department preserves revisions rather than pretending that any design is complete.[NEWLINE][NEWLINE]Each qualifying Building Class earns one empire-wide reward of 12 Culture and 20 Gold on Standard speed, rounded individually using the active construction percentage. Possession is checked at PlayerDoTurn; a building removed before this evaluation earns nothing. Production, purchases, gifts, free buildings and captures all count if the qualifying building remains. Unique replacements share their ordinary Building Class. Wonders, the Palace, hidden dummies and nonconstructible special buildings are excluded.[NEWLINE][NEWLINE]The rewarded-class ledger survives losses, reconstruction, recapture and save/load. Revision Workshop Science instead counts CURRENT qualifying classes in that individual city. An existing progressed save with no ledger seeds already-owned classes without retroactive rewards.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_CIV_PEDIA','The Republic of First Drafts unites writers, architects, engineers, scholars and publishers around one conviction: Nothing Is Ever Final. Its government rewards new institutions and treats experimentation as a civic duty. The Editorial Department preserves revisions rather than pretending that any design is complete.[NEWLINE][NEWLINE]Each qualifying Building Class earns one empire-wide reward of 12 Culture and 20 Gold on Standard speed, rounded individually using the active construction percentage. Possession is checked at PlayerDoTurn; a building removed before this evaluation earns nothing. Production, purchases, gifts, free buildings and captures all count if the qualifying building remains. Unique replacements share their ordinary Building Class. Wonders, the Palace, hidden dummies and nonconstructible special buildings are excluded.[NEWLINE][NEWLINE]The rewarded-class ledger survives losses, reconstruction, recapture and save/load. Revision Workshop Science instead counts CURRENT qualifying classes in that individual city. An existing progressed save with no ledger seeds already-owned classes without retroactive rewards.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_DAWN','Esteemed Editor-in-Chief Marginalia, First Author of the Republic, your people await your next great revision.[NEWLINE][NEWLINE]Throughout history, civilizations have constructed monuments, established institutions and recorded their achievements for future generations.[NEWLINE][NEWLINE]Yet your people have recognized a fundamental truth.[NEWLINE][NEWLINE]No creation is ever truly complete.[NEWLINE][NEWLINE]Every building can be improved. Every discovery can be reconsidered. Every great work begins with an imperfect first draft.[NEWLINE][NEWLINE]Now, the scattered scholars and architects of your Republic have united beneath a common purpose.[NEWLINE][NEWLINE]Build your cities. Gather your knowledge. Let every new institution become another chapter in the history of your people.[NEWLINE][NEWLINE]Will you write the greatest civilization the world has ever known?[NEWLINE][NEWLINE]Or will history remember you as another unfinished manuscript?');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_DEFEAT_1','I see... perhaps... we should have considered another draft.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_DUMMY','Editorial Research');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_DUMMY_HELP','Internal Revision Workshop Science. Automatically reconciled; cannot be built, bought or sold.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_FRIENDLY_1','A welcome collaborator! Please, take a seat among the manuscripts.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_GREETING_1','Welcome, esteemed visitor! Before we begin negotiations, I must ask you to review the seventeen amendments to our preliminary diplomatic introduction.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_HOSTILE_1','I have read your latest actions. The margins are now entirely red.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_LEADER','Editor-in-Chief Marginalia');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_LEADER_PEDIA','Editor-in-Chief Marginalia governs in an enormous robe embroidered with annotations. Her slightly crooked spectacles have survived seventeen proposed replacements. From a desk buried in unfinished manuscripts she oversees the Editorial Department, accepting revisions from engineers and poets with equal seriousness. Her authority rests on the belief that even the republic itself remains open to improvement.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_MARGINALIA_HEADING_1','Authority in the Margins');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_MARGINALIA_LIVED','The age of continuous revision');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_MARGINALIA_NAME','Editor-in-Chief Marginalia');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_MARGINALIA_SUBTITLE','First Author of the Republic');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_MARGINALIA_TEXT_1','Editor-in-Chief Marginalia governs in an enormous robe embroidered with annotations. Her slightly crooked spectacles have survived seventeen proposed replacements. From a desk buried in unfinished manuscripts she oversees the Editorial Department, accepting revisions from engineers and poets with equal seriousness. Her authority rests on the belief that even the republic itself remains open to improvement.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_MARGINALIA_TITLES_1','Editor-in-Chief and Chair of the Editorial Department');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_NEUTRAL_1','Your proposal is on the desk. Somewhere beneath the other proposals.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_PEACE_1','Let us strike out this unfortunate chapter and begin a fresh page.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_PEACE_OFFER_1','The board proposes a revision to our present hostilities.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_SHORT','The Republic of First Drafts');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_SIGHT','Surveying the Margins');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_SIGHT_HELP','+1 Sight. Lost on upgrade. Automatically granted to Ink Mortars; cannot be selected.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_SPY_1','Redactor');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_SPY_10','Second Reading');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_SPY_2','Footnote');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_SPY_3','Erratum');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_SPY_4','Palimpsest');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_SPY_5','Semicolon');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_SPY_6','Addendum');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_SPY_7','Proofreader');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_SPY_8','Black Quill');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_SPY_9','Appendix');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_STRATEGY','Intermediate complexity (3/5). Diversify ordinary buildings across your empire for permanent first-class Culture and Gold rewards. Develop individual cities toward 4, 8 and 12 qualifying classes for Revision Workshop Science. Use Ink Mortars for positioning and awareness. Science and Culture are the preferred victories.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_TRADE_1','Approved, with only a modest number of footnotes.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_TRAIT','Nothing Is Ever Final');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_TRAIT_HELP','The first time your civilization possesses a new qualifying non-wonder Building Class, gain 12 [ICON_CULTURE] Culture and 20 [ICON_GOLD] Gold (scaled by game speed). Each Building Class can grant this reward only once. Buildings must still be present at the next owner-turn evaluation.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_UNIT','Ink Mortar');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_UNIT_HELP','Replaces the Catapult. Has +1 Movement and +1 Sight compared to the normal Catapult. Retains normal siege setup requirements, attacks and upgrade paths. The additional Sight is lost on upgrade.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_UNIT_PEDIA','An Ink Mortar launches industrial barrels of black ink with the same mechanical discipline as an ordinary Catapult. Its crews learn to read terrain as carefully as a proofreader reads a manuscript. The ink is a matter of national style; the weapon has no additional city damage, special attack or ink debuff.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_UNIT_STRATEGY','Move the Ink Mortar into useful siege positions and use its additional Sight to survey approaches. All normal Catapult combat, setup, resource and attack rules still apply.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_WAR_1','Your civilization has been reviewed. Unfortunately, the editorial board has recommended its complete removal.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_WORKSHOP','Revision Workshop');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_WORKSHOP_HELP','Replaces the Workshop. Retains its normal benefits and provides +1 [ICON_CULTURE] Culture. Gains +1 [ICON_RESEARCH] Science for every 4 distinct qualifying Building Classes currently present in this city, up to +3 Science. The Revision Workshop counts toward this total.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_WORKSHOP_PEDIA','The Editorial Department directs the Republic''s Revision Workshops: government engineering institutions where architects annotate blueprints, scholars examine prototypes and engineers submit the next version. Every existing institution offers another useful design problem. Their Science reflects the city''s current architectural diversity, independent of the permanent national reward ledger.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_RFD_WORKSHOP_STRATEGY','Develop a broad collection of ordinary city institutions. Including the Revision Workshop, 4, 8 and 12 qualifying classes provide 1, 2 and 3 additional Science. Losing buildings can reduce this Science. The additional Culture remains while the Workshop exists.');
